#include "modules/orbipom_state.hpp"
#include "core/data/json.hpp"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iostream>
#include <limits>
#include <stdexcept>

namespace m=endfield::modules;using P=endfield::core::Point;using J=ehud::data::Json;
namespace {
unsigned checks{};
void check(bool value,const char*why){++checks;if(!value)throw std::runtime_error(why);}
struct Port final:m::OrbiPomRuntimePort {
    m::OrbiPomSnapshot value;std::optional<std::string>failure;unsigned starts{},advances{},moves{},ups{},drops{},activations{},cancels{},pauses{},hydrates{};P last{};bool finish{},failStart{};
    const m::OrbiPomSnapshot&snapshot()const noexcept override{return value;}
    const std::optional<std::string>&error()const noexcept override{return failure;}
    void start(std::optional<std::uint32_t>)override{++starts;const auto high=value.highScore;value={};value.state="playing";value.highScore=high;if(failStart)failure="Synthetic original-runtime error";}
    void advance(double seconds)override{++advances;value.simulationTime+=seconds;if(finish)value.state="over";}
    void move(P p)override{++moves;last=p;value.previewX=p.x;}
    void pointerUp(P p)override{++ups;last=p;}
    bool drop()override{++drops;return value.canAdvance();}
    bool activate(m::OrbiPomSkill s)override{++activations;value.skill=s;value.skillPhase="selecting";return true;}
    void cancelSkill()override{++cancels;value.skill.reset();value.skillPhase.reset();}
    void pause(bool valueIn)override{++pauses;value.paused=valueIn;}
    void highScore(std::int64_t high)override{++hydrates;value.highScore=high;}
};
struct Fixture {
    Port*port{};unsigned creations{};std::vector<std::int64_t>saves;std::vector<m::OrbiPomEvent>events;
    m::OrbiPomSessionCallbacks callbacks(){return {[this]{++creations;auto p=std::make_unique<Port>();port=p.get();return p;},[this](auto score){saves.push_back(score);},[this](auto event){events.push_back(event);}};}
};
void source(const char*path){
    std::ifstream file(path);check(bool(file),"Explicit original-source fixture opens");const std::string bytes(std::istreambuf_iterator<char>(file),{});const auto root=J::parse(bytes,128*1024);
    check(root["originalRuntimeChecks"].integer()==108,"Fixture was generated by all original physics/skill tests");
    constexpr std::array states{"idle","playing","over"};const std::array<std::optional<std::string>,4>phases{std::nullopt,"armed","selecting","casting"};
    for(const auto&row:root["availability"].array()){
        const auto&a=row.array();m::OrbiPomSnapshot s;s.state=states.at(a[0].integer());s.paused=a[1].integer()!=0;s.skillPhase=phases.at(a[2].integer());s.energy=int(a[3].integer());s.swapCharge=int(a[4].integer());int mask{};
        for(int i=0;i<4;++i)if(s.canUse(static_cast<m::OrbiPomSkill>(i)))mask|=1<<i;
        check(mask==a[5].integer(),"Availability exactly matches original Swift snapshot predicate");
    }
    // The v1.2.0 board geometry of this fixture (worlds) is not consumed: the
    // 1.3.0 board (unit 1.2, drop zone) is OrbiPomCanvas's, checked against
    // the canvas oracle in orbipom_canvas_tests.
    std::size_t total{};for(const auto&frame:root["frames"].array())total+=frame["snapshot"]["bodies"].array().size();
    check(root["frames"].array().size()==11&&total>30,"Seeded actual engine transcript includes ten seconds of moving/merged bodies");
}
void session(){
    Fixture f;m::OrbiPomSession session(51,f.callbacks());check(!session.hasRuntime()&&session.snapshot().state=="idle"&&session.bestScore()==51,"Idle state keeps runtime lazy and local score");session.advance(1);session.move({1,2});check(f.creations==0,"Hidden/no-runtime calls do not instantiate engine");
    check(session.start(123)&&f.creations==1&&f.port->hydrates==1&&session.snapshot().highScore==51&&f.events==std::vector{m::OrbiPomEvent::started},"First start hydrates only injected best and emits one event");
    f.port->value.score=73;check(session.bestSoFar()==73&&session.bestScore()==51&&f.saves.empty(),"bestSoFar includes the current game without saving it (OrbiPomSession.swift:49-51)");session.pause(true);check(session.bestScore()==73&&f.saves==std::vector<std::int64_t>{73},"Pause commits improved local best once");session.pause(true);check(f.saves.size()==1,"Repeated hidden pause does not rewrite best");
    const auto calls=f.port->advances;session.advance(300);check(f.port->advances==calls,"Paused runtime receives no simulation call");session.setManuallyPaused(true);session.pause(false);check(session.snapshot().paused,"Visibility resume cannot override user pause");session.setManuallyPaused(false);check(session.snapshot().paused,"Clearing manual intent alone waits for visibility reconciliation");session.pause(false);
    session.advance(std::numeric_limits<double>::quiet_NaN());session.advance(-1);session.advance(0);check(f.port->advances==calls,"Invalid elapsed time never reaches engine");session.move({NAN,1});session.pointerUp({1,INFINITY});check(f.port->moves==0&&f.port->ups==0,"Nonfinite pointer cannot reach original runtime");
    f.port->value.score=94;f.port->finish=true;session.advance(1./60);session.advance(1./60);check(f.events==std::vector{m::OrbiPomEvent::started,m::OrbiPomEvent::finished}&&f.saves.back()==94,"Finished transition commits once and only once");
    check(session.start(456)&&f.creations==1&&f.port->starts==2&&f.events.back()==m::OrbiPomEvent::restarted,"Restart reuses one VM and session best");
    m::OrbiPomSession unavailable(-1);check(!unavailable.start()&&!unavailable.hasRuntime()&&unavailable.error()&&unavailable.bestScore()==0,"Missing actual physics runtime stays explicitly unavailable");
    Fixture failing;m::OrbiPomSession failure(0,{[&]{auto p=std::make_unique<Port>();p->failStart=true;failing.port=p.get();return p;},{},[&](auto event){failing.events.push_back(event);}});check(!failure.start()&&failure.hasRuntime()&&failure.error()&&failing.events.empty(),"Original runtime failure publishes no successful Start event");
}
}
int main(int argc,char**argv){try{check(argc==2,"Pass immutable original OrbiPom fixture");source(argv[1]);session();std::cout<<"PASS "<<checks<<" OrbiPom source/session checks\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}}
